package generate

import (
	"crypto/sha256"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"slices"
	"strconv"
	"strings"
)

// Export records a public accessor and the normalized artwork it represents.
// Keep this manifest under version control to detect naming-policy changes.
type Export struct {
	Name   string `json:"name"`
	ID     string `json:"id"`
	SHA256 string `json:"sha256"`
}

func artworkHash(svg string) string { return fmt.Sprintf("%x", sha256.Sum256([]byte(svg))) }

// ReadExports reads accessors from a previously generated file, including
// compatibility aliases. It does not execute code or load imported packages.
func ReadExports(source []byte) ([]Export, error) {
	if len(source) == 0 {
		return nil, nil
	}
	if !strings.HasPrefix(string(source), "// Code generated by mygoicons ") {
		return nil, fmt.Errorf("not a mygoicons generated file")
	}
	f, err := parser.ParseFile(token.NewFileSet(), "icons_gen.go", source, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	var exports []Export
	targets := map[string]string{}
	hashes := map[string]string{}
	for _, decl := range f.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || !fn.Name.IsExported() {
			continue
		}
		words := strings.Fields(fn.Doc.Text())
		if len(words) < 4 || words[0] != fn.Name.Name || words[1] != "is" {
			return nil, fmt.Errorf("unrecognized accessor %s", fn.Name.Name)
		}
		_, id, ok := strings.Cut(words[3], ":")
		if !ok {
			return nil, fmt.Errorf("missing Iconify ID for %s", fn.Name.Name)
		}
		exports = append(exports, Export{Name: fn.Name.Name, ID: id})
		ast.Inspect(fn.Body, func(n ast.Node) bool {
			if lit, ok := n.(*ast.BasicLit); ok && lit.Kind == token.STRING {
				if svg, err := strconv.Unquote(lit.Value); err == nil {
					hashes[fn.Name.Name] = artworkHash(svg)
				}
			}
			if call, ok := n.(*ast.CallExpr); ok {
				if target, ok := call.Fun.(*ast.Ident); ok {
					targets[fn.Name.Name] = target.Name
				}
			}
			return true
		})
	}
	for i := range exports {
		name := exports[i].Name
		for range len(exports) + 1 {
			if hash := hashes[name]; hash != "" {
				exports[i].SHA256 = hash
				break
			}
			name = targets[name]
		}
		if exports[i].SHA256 == "" {
			return nil, fmt.Errorf("cannot identify artwork for %s", exports[i].Name)
		}
	}
	slices.SortFunc(exports, func(a, b Export) int { return strings.Compare(a.Name, b.Name) })
	return exports, nil
}

func compatibleExports(current, previous []Export) ([]Export, map[string]string, error) {
	byName, byID := map[string]Export{}, map[string]Export{}
	byHash := map[string][]Export{}
	for _, e := range current {
		byName[e.Name] = e
		byID[e.ID] = e
		byHash[e.SHA256] = append(byHash[e.SHA256], e)
	}
	aliases := map[string]string{}
	for _, old := range previous {
		if !token.IsExported(old.Name) || !token.IsIdentifier(old.Name) {
			return nil, nil, fmt.Errorf("invalid previous export %q", old.Name)
		}
		target, exists := byID[old.ID]
		if !exists {
			matches := byHash[old.SHA256]
			if len(matches) != 1 {
				return nil, nil, fmt.Errorf("compatibility: %s (%s) was removed; no unique identical replacement (found %d); retain upstream alias or explicitly review the manifest", old.Name, old.ID, len(matches))
			}
			target = matches[0]
		}
		if now, ok := byName[old.Name]; ok {
			if now.ID != target.ID {
				return nil, nil, fmt.Errorf("compatibility: export %s changed identity from %s to %s", old.Name, old.ID, now.ID)
			}
			continue
		}
		alias := Export{Name: old.Name, ID: target.ID, SHA256: target.SHA256}
		current = append(current, alias)
		byName[old.Name] = alias
		aliases[old.Name] = target.Name
	}
	slices.SortFunc(current, func(a, b Export) int { return strings.Compare(a.Name, b.Name) })
	return current, aliases, nil
}
